def _propagate_from(cell):
    """Recompute every compute cell downstream of ``cell``."""
    affected = []
    pending = list(cell._dependents)
    seen = set()

    while pending:
        dependent = pending.pop()
        identifier = id(dependent)
        if identifier in seen:
            continue
        seen.add(identifier)
        affected.append(dependent)
        pending.extend(dependent._dependents)

    affected.sort(key=lambda dependent: dependent._depth)

    changed = []
    for dependent in affected:
        new_value = dependent._compute(
            [input_cell.value for input_cell in dependent._inputs]
        )
        if new_value != dependent._value:
            dependent._value = new_value
            changed.append(dependent)

    for dependent in changed:
        for callback in list(dependent._callbacks):
            callback(dependent._value)


class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._dependents = []
        self._depth = 0

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        if new_value != self._value:
            self._value = new_value
            _propagate_from(self)


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self._inputs = list(inputs)
        self._compute = compute_function
        self._callbacks = []
        self._dependents = []
        self._depth = (
            max(input_cell._depth for input_cell in self._inputs) + 1
            if self._inputs
            else 0
        )

        for input_cell in self._inputs:
            input_cell._dependents.append(self)

        self._value = self._compute(
            [input_cell.value for input_cell in self._inputs]
        )

    @property
    def value(self):
        return self._value

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        try:
            self._callbacks.remove(callback)
        except ValueError:
            pass

